class Disp { void update(float t, float h, float p) { } }
class Wf {
  float t, h, p;
  Disp current = new Disp(), stats = new Disp(), forecast = new Disp();
  void measurementsChanged() {
    current.update(t, h, p);
    stats.update(t, h, p);
    forecast.update(t, h, p);
  }
}

interface Observer { void update(float t, float h, float p); }
class Disp { void update(float t, float h, float p) { } }
class Wd {
  float t, h, p;
  Disp current = new Disp(), stats = new Disp();
  List<Observer> observers = new ArrayList<>();
  void before() {
    current.update(t, h, p);
    stats.update(t, h, p);
  }
  void after() {
    for (Observer o : observers) {
      o.update(t, h, p);
    }
  }
}

