interface Node {}
record Item(String name, int calories) implements Node {}
record Menu(List<Node> kids) implements Node {}
interface Visitor { void visit(Item i); }
class CalorieCount implements Visitor { int total; public void visit(Item i) { total += i.calories(); } }
class Traverser {
    void walk(Node n, Visitor v) {
        if (n instanceof Menu m) m.kids().forEach(k -> walk(k, v)); else v.visit((Item) n);
    }
}
CalorieCount c = new CalorieCount();
new Traverser().walk(new Menu(List.of(new Item("pie", 300), new Item("tea", 20))), c); System.out.println(c.total);

