interface Command { void execute(); }
record Macro(Command[] parts) implements Command {
  public void execute() { for (Command c : parts) c.execute(); }
}
class Run { public static void main(String[] args) {
  Command dim = () -> System.out.println("dim");
  Command music = () -> System.out.println("music");
  Command party = new Macro(new Command[] { music, dim });
