interface Command { void execute(); void undo(); }
record Step(String n) implements Command {
  public void execute() { System.out.println("do " + n); }
  public void undo() { System.out.println("undo " + n); }
}
record Macro(Command[] parts) implements Command {
  public void execute() { for (Command c : parts) c.execute(); }
  public void undo() { for (int i = parts.length - 1; i >= 0; i--) parts[i].undo(); }
}
class Run { public static void main(String[] args) {
  Command m = new Macro(new Command[] { new Step("x"), new Step("y"), new Step("z") });
  m.execute(); m.undo(); } }

