class Turnstile {
  public static void main(String[] args) {
    S s = S.LOCKED;
    for (String a : new String[]{"push", "coin", "coin", "push"}) {
      s = next(s, a);
      System.out.print(s + " ");
    }
  }
  static S next(S s, String a) {
    if (s == S.LOCKED && a.equals("coin")) return S.OPEN;
    if (s == S.OPEN && a.equals("push")) return S.LOCKED;
    return s;
  }
}
enum S { LOCKED, OPEN }

class Machine {
  static final int NO_Q = 0, HAS_Q = 1;
  int state = NO_Q;
  void insert() {
    if (state == NO_Q) { state = HAS_Q; System.out.print("ok "); }
    else System.out.print("no ");
  }
  void eject() {
    if (state == HAS_Q) { state = NO_Q; System.out.print("back "); }
    else System.out.print("none ");
  }
  public static void main(String[] a) {
    Machine m = new Machine();
    m.insert(); m.insert(); m.eject(); m.eject();
  }
}

