class Link {
    final Predicate<String> test; final String name; Link next;
    Link(String name, Predicate<String> test) { this.name = name; this.test = test; }
    Link then(Link n) { next = n; return n; }
    String handle(String m) {
        if (test.test(m)) return name + " took " + m;
        return next == null ? "unhandled " + m : next.handle(m);
    }
}
Link fan = new Link("Fan", m -> m.startsWith("love"));
fan.then(new Link("Legal", m -> m.contains("kids")));
System.out.println(fan.handle("hello kids") + " / " + fan.handle("hello"));

class Link {
    final String name; final Predicate<String> test; Link next;
    Link(String n, Predicate<String> t) { name = n; test = t; }
    String handle(String m) {
        if (test.test(m)) return name + " took " + m;
        return "unhandled " + m;
    }
}
Link fan = new Link("Fan", m -> m.startsWith("love"));
fan.next = new Link("Legal", m -> m.contains("kids"));
System.out.println(fan.handle("hello kids"));

class Coin { static int made; Coin() { made++; } }
class CoinPool {
    private Coin shared;
    Coin get() { if (shared == null) shared = new Coin(); return shared; }
}
CoinPool p = new CoinPool();
for (int i = 0; i < 1000; i++) p.get();
System.out.println(Coin.made);

interface Expr { int eval(Deque<String> in); }
class Num implements Expr {
    public int eval(Deque<String> in) { return Integer.parseInt(in.pop()); }
}
class Add implements Expr {
    public int eval(Deque<String> in) { in.pop(); return new Num().eval(in) + new Num().eval(in); }
}
System.out.println(new Add().eval(new ArrayDeque<>(List.of("add", "4", "5"))));

