interface Node {}
record Item(int calories) implements Node {}
record Menu(List<Node> kids) implements Node {}
class Traverser {
    void walk(Node n, IntConsumer v) {
        if (n instanceof Menu m) m.kids().forEach(k -> walk(k, v)); else v.accept(((Item) n).calories());
    }
}
int[] total = {0};
Node menu = new Menu(List.of(new Item(300), new Menu(List.of(new Item(120), new Item(80)))));
new Traverser().walk(menu, c -> total[0]++);
System.out.println(total[0]);

interface Rule { int fee(int km); }
class Flat implements Rule { public int fee(int km) { return 5; } }
class PerKm implements Rule { public int fee(int km) { return 2 * km; } }
class Trip {
    Rule rule = new Flat();
    int price(int km) { return rule.fee(km); }
}
// main:
Trip t = new Trip();
int first = t.price(10);
t.rule = new PerKm();
System.out.println(first + " " + t.price(10));

interface Mode { Mode press(); }
class Off implements Mode { public Mode press() { return new On(); } }
class On implements Mode { public Mode press() { return new Off(); } }
class Switch { Mode m = new Off(); void press() { m = m.press(); } }
// main:
Switch s = new Switch(); s.press(); s.press(); s.press();
System.out.println(s.m.getClass().getSimpleName());

interface Greeter { String hi(String n); }
class Plain implements Greeter { public String hi(String n) { return "Hi " + n; } }
class Shout implements Greeter {
    Greeter g; Shout(Greeter g) { this.g = g; }
    public String hi(String n) { return g.hi(n).toUpperCase(); }
}
class Guard implements Greeter {
    Greeter g; Guard(Greeter g) { this.g = g; }
    public String hi(String n) { return n.isEmpty() ? "denied" : g.hi(n); }
}
// main:
System.out.println(new Shout(new Plain()).hi("ann") + "," + new Guard(new Plain()).hi(""));

